import numpy as np
from scipy.linalg import svd, eig, norm


def five_point_algorithm_self(matches_in_meters):
    """
    Args:
        matches_in_meters: A (5, 3, 2) numpy array storing 5 matches.
                           Shape is (5, 3, 2) -> (num_points, coords, num_views)
    Returns:
        Es: A list of valid 3x3 essential matrices.
    """
    # Adjusting indexing: Python 0:3 is MATLAB 1:3
    Q1 = matches_in_meters[:, :, 0]
    Q2 = matches_in_meters[:, :, 1]

    # Construct Q matrix
    # Note: reshape behavior. We want element-wise multiplication of columns.
    Q = np.column_stack([
        Q2[:, 0] * Q1[:, 0],
        Q2[:, 0] * Q1[:, 1],
        Q2[:, 0] * Q1[:, 2],
        Q2[:, 1] * Q1[:, 0],
        Q2[:, 1] * Q1[:, 1],
        Q2[:, 1] * Q1[:, 2],
        Q2[:, 2] * Q1[:, 0],
        Q2[:, 2] * Q1[:, 1],
        Q2[:, 2] * Q1[:, 2]
    ])

    # SVD
    # python svd returns U, S, Vh (transpose of V)
    # MATLAB: [~, ~, V] = svd(Q); EE = V(:,6:9);
    # In Python, Vh rows are V columns. We need the last 4 rows of Vh.
    U, S, Vh = svd(Q)
    EE = Vh[-4:].T  # Take last 4 rows (corresponding to smallest singular values) and transpose

    # Reshaping Vectors to Matrices
    # MATLAB: E1 = reshape(EE(:,1), [3,3])'
    # MATLAB reshape is Column-Major, then Transpose makes it Row-Major.
    # Python reshape is Row-Major by default. So vec.reshape(3,3) is equivalent to MATLAB's reshape(vec, [3,3])'
    E1 = EE[:, 0].reshape(3, 3)
    E2 = EE[:, 1].reshape(3, 3)
    E3 = EE[:, 2].reshape(3, 3)
    E4 = EE[:, 3].reshape(3, 3)

    C = compute_coefficients(E1, E2, E3, E4)

    # MATLAB Indices: 1:4, 11:13, 17:18, 20 (1-based)
    # Python Indices: 0:4, 10:13, 16:18, 19 (0-based)
    idx_c1 = np.r_[0:4, 10:13, 16:18, 19]
    C1 = C[:, idx_c1]

    # MATLAB: [zeros(10,4) C(:,[5:7,14:15,19])]
    # Python Indices: 4:7, 13:15, 18
    idx_c2 = np.r_[4:7, 13:15, 18]
    C2 = np.hstack([np.zeros((10, 4), dtype=C.dtype), C[:, idx_c2]])

    # MATLAB: [zeros(10,7) C(:,[8:9,16])]
    # Python Indices: 7:9, 15
    idx_c3 = np.r_[7:9, 15]
    C3 = np.hstack([np.zeros((10, 7), dtype=C.dtype), C[:, idx_c3]])

    # MATLAB: [zeros(10,9) C(:,10)] -> Index 9 in Python
    C4 = np.hstack([np.zeros((10, 9), dtype=C.dtype), C[:, [9]]])

    Es = polyeig4(C1, C2, C3, C4, E1, E2, E3, E4)
    return Es


def compute_coefficients(E1, E2, E3, E4):
    # Unpack matrices to scalar variables for the long equation
    e1_1_1, e1_1_2, e1_1_3 = E1[0, 0], E1[0, 1], E1[0, 2]
    e1_2_1, e1_2_2, e1_2_3 = E1[1, 0], E1[1, 1], E1[1, 2]
    e1_3_1, e1_3_2, e1_3_3 = E1[2, 0], E1[2, 1], E1[2, 2]

    e2_1_1, e2_1_2, e2_1_3 = E2[0, 0], E2[0, 1], E2[0, 2]
