def polyeig4(A0, A1, A2, A3, E1, E2, E3, E4):
    n = A0.shape[0]
    p = 3
    np_dim = n * p

    # Construct A matrix
    A = np.eye(np_dim, dtype=A0.dtype)
    A[:n, :n] = A0

    # Construct B matrix
    nB = A.shape[0]
    B = np.zeros((nB, nB), dtype=A0.dtype)
    # MATLAB: B((n+1):(nB+1):end) = 1 (Diagonal setting starting from n+1)
    # This sets the diagonal of the bottom-right 2n x 2n block to 1
    # Indices in Python: (n, n), (n+1, n+1) ... (nB-1, nB-1)
    for i in range(n, nB):
        B[i, i] = 1.0

    # MATLAB: B(1:n, 1:end) = -[A1, A2, A3]
    B[:n, :] = -np.hstack([A1, A2, A3])

    # Generalized Eigenvalue Problem: A*v = lambda*B*v
    # scipy.linalg.eig returns (w, vr) where w are eigenvalues, vr are right eigenvectors
    w, vr = eig(A, B)

    Em = []

    for j in range(len(w)):
        # Check finite and real-ish
        if np.isfinite(w[j]) and abs(w[j].imag) < 1e-8:
            e = w[j].real
            V_vec = vr[:, j].real

            # Normalize eigenvector to unit 2-norm (MATLAB eig returns unit-norm vectors)
            vnorm = norm(V_vec, 2)
            if vnorm < 1e-12:
                continue
            V_vec = V_vec / vnorm

            # Extract first n elements corresponds to V in MATLAB code
            # Note: The MATLAB code logic says V(:) = real(X(:, j)), but X is size np_dim x np_dim
            # Then it extracts v using a residual check.

            # Reconstruct the polynomial residual logic from MATLAB
            e2 = e * e
            e3 = e2 * e

            # V in MATLAB logic is reshaped from the eigenvector X(:,j)
            # But wait, MATLAB V(:) = X(:, j) means V is size (n, p) = (10, 3)
            # Python reshape order 'F' to match MATLAB's linear indexing fill
            V_matrix = V_vec.reshape(n, p, order='F')

            # R = (A0 + e*A1 + e2*A2 + e3 * A3) * V
            R = (A0 + e * A1 + e2 * A2 + e3 * A3) @ V_matrix

            # res = sum(abs(R)) ./ sum(abs(V))
            res = np.sum(np.abs(R), axis=0) / np.sum(np.abs(V_matrix), axis=0)

            ind = np.argmin(res)
            v_final = V_matrix[:, ind]

            # v = v([8,9,10]) -> Python indices 7, 8, 9
            v_reduced = v_final[[7, 8, 9]]
            norm_val = norm(v_reduced, 2)

            if norm_val > 1e-10:  # Avoid division by zero
                v_reduced = v_reduced / norm_val

                # Compute Essential Matrix
                # E = v(1)*E1 + v(2)*E2 + (v(3)*e)*E3 + v(3)*E4
                E = v_reduced[0] * E1 + v_reduced[1] * E2 + (v_reduced[2] * e) * E3 + v_reduced[2] * E4

                # Check valid (finite and rank >= 2)
                if np.all(np.isfinite(E)) and np.linalg.matrix_rank(E) >= 2:
                    Em.append(E)

    return Em
